/bin/bash -lc "python - <<'PY'
from sim import Sim
import mujoco
for name,idx in [('home',None),('lhip+',2),('lhip-',2),('rhip+',7),('rhip-',7),('lknee+',3),('lankle+',4),('torso+',10),('torso-',10)]:
    sim=Sim(); ctrl=sim.home_ctrl()
    if idx is not None:
        ctrl[idx]+=0.4 if '+' in name else -0.4
    for _ in range(200):
        sim.data.ctrl[:]=ctrl; sim.step()
    print('\\n',name,'pelvis',sim.pelvis_position(),'torso_up',sim.torso_up())
    for bid in [6,11]:
        print(mujoco.mj_id2name(sim.model,mujoco.mjtObj.mjOBJ_BODY,bid), sim.data.xpos[bid])
PY"

